sys_script_include.script:
var MSSCustodyDataMigration = Class.create();
MSSCustodyDataMigration.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    revertMigration: function(tradesID) {

        try {

            gs.info('HSBC Trade and Task Migration - tradesID are:' + tradesID);

            var custHisTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task_passive');
            custHisTask.addEncodedQuery('trade_idIN' + tradesID);
            custHisTask.sys_class_name = 'x_hsb11_mss_c_proc_mss_custody_task';
            custHisTask.setWorkflow(false);
            custHisTask.autoSysFields(false);
            custHisTask.updateMultiple();
            gs.info('HSBC Trade and Task Migration - tasks updated');

            var custHisCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case_passive');
            custHisCase.addEncodedQuery('trade_idIN' + tradesID);
            custHisCase.sys_class_name = 'x_hsb11_mss_c_proc_mss_custody_case';
            custHisCase.setWorkflow(false);
            custHisCase.autoSysFields(false);
            custHisCase.updateMultiple();
            gs.info('HSBC Trade and Task Migration - cases updated');

            var custHisTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
            custHisTrade.addEncodedQuery('sys_idIN' + tradesID);
            custHisTrade.sys_class_name = 'x_hsb11_mss_c_proc_mss_custody_trade';
            custHisTrade.setWorkflow(false);
            custHisTrade.autoSysFields(false);
            custHisTrade.updateMultiple();
            gs.info('HSBC Trade and Task Migration - trades updated');

            gs.eventQueue("x_hsb11_mss_c_proc.revert_cust_journalau", current, tradesID, '');

            return 'Success';

        } catch (error) {
            gs.error('Custody Revert Migration Error: error in moving Custody trades ' + tradesID + ' back to active tables:' + error.message);
            return 'Fail';

        }
    },

    setSwiftLinkingFlag: function(tradeID, flag) {

        try {
         //   gs.info('chinmay set swift linking function called');
            var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            trade.get(tradeID);
		//	gs.info('chinmay inside swift linking' + trade.sys_class_name);
            trade.swift_linking_flag = flag;
			trade.update();
        }
		catch(error){
			gs.error('CustodySwift linking Flag error'+trade.trade_id);
		}
    },

    type: 'MSSCustodyDataMigration'
});
